const entry = (($json.body && $json.body.entry) || $json.entry || [])[0] || {};
const change = (entry.changes || [])[0] || {};
const value = change.value || {};

const cfg = await (await fetch('http://localhost:8090/api/config')).json();

const version = (cfg.meta && cfg.meta.version) || 'v25.0';
const token = (cfg.meta && cfg.meta.access_token) || '';
const phone = (value.metadata && value.metadata.phone_number_id) || (cfg.meta && cfg.meta.phone_number_id) || '';
const waba = (cfg.meta && cfg.meta.waba_id) || entry.id || '';
const be = (cfg.meta && cfg.meta.business_events) || {};
const beEnabled = !!be.enabled;

async function registerEvent(conversationId, eventValue) {
  if (!beEnabled) return { skipped: 'disabled' };
  if (!waba) return { skipped: 'no_waba_id' };
  if (!conversationId) return { skipped: 'no_conversation_id' };
  try {
    const ev = {
      event_type: be.event_type || 'lead',
      event_timestamp: Math.floor(Date.now() / 1000)
    };
    if (eventValue !== undefined && eventValue !== null) ev.event_value = eventValue;
    if (be.currency) ev.event_metadata = { currency: be.currency };
    const r = await fetch('https://graph.facebook.com/' + version + '/' + waba + '/business_events', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: JSON.stringify({ conversation_id: conversationId, business_events: [ev] })
    });
    return { status: r.status, body: await r.text() };
  } catch (e) {
    return { error: String(e) };
  }
}

// branch 1: notificação de entrega -> registra o evento na 1ª 'sent'
if (value.statuses && value.statuses.length) {
  const st = value.statuses[0];
  const convId = st.conversation && st.conversation.id;
  if (st.status === 'sent' && convId) {
    const beResult = await registerEvent(convId);
    return [{ evento: 'business_event', status: st.status, business_events: beResult }];
  }
  return [];
}

// branch 2: mensagem recebida -> responde
if (!value.messages || !value.messages.length) return [];
const msg = value.messages[0];
const from = msg.from || '';
const texto = (msg.type === 'text' && msg.text) ? msg.text.body : '';
if (!from || !texto) return [];

const repl = (s) => (s || '')
  .replaceAll('{{agente_nome}}', cfg.agente_nome || '')
  .replaceAll('{{empresa_nome}}', cfg.empresa_nome || '')
  .replaceAll('{{servico_principal}}', cfg.servico_principal || '')
  .replaceAll('{{criterio_alto_valor}}', cfg.criterio_alto_valor || '')
  .replaceAll('{{link_app}}', cfg.link_app || '')
  .replaceAll('{{base_conhecimento}}', cfg.base_conhecimento || '');
const system = repl(cfg.system_message).replaceAll('{{modelos}}', JSON.stringify(cfg.modelos || []));

const base = (cfg.llm && cfg.llm.base_url) || 'http://127.0.0.1:8888/v1';
const model = (cfg.llm && cfg.llm.model) || 'Qwen/Qwen2.5-14B-Instruct-GGUF';
const llm = await fetch(base + '/chat/completions', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + ((cfg.llm && cfg.llm.api_key) || '') },
  body: JSON.stringify({ model, messages: [{ role: 'system', content: system }, { role: 'user', content: texto }], max_tokens: 400 })
});
const llmJson = await llm.json();
const resposta = ((((llmJson.choices || [])[0] || {}).message || {}).content || '').trim();
if (!resposta) return [{ erro: 'sem resposta do LLM', llm_status: llm.status }];

const wa = await fetch('https://graph.facebook.com/' + version + '/' + phone + '/messages', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
  body: JSON.stringify({ messaging_product: 'whatsapp', to: from, type: 'text', text: { body: resposta } })
});

return [{ resposta, wa_status: wa.status }];
